inline std::string sha(const Bytes& bytes){ts::SHA256 hash;uint8_t digest[ts::SHA256::HASH_SIZE];if(!hash.init()||!hash.add(bytes.data(),bytes.size())||!hash.getHash(digest,sizeof(digest)))throw std::runtime_error("Content SHA-256 unavailable");auto text=hex(digest,sizeof(digest));std::transform(text.begin(),text.end(),text.begin(),[](char c){return char(std::tolower(c));});return text;}
inline bool utf8(const Bytes& b){for(size_t p=0;p<b.size();){unsigned c=b[p++],value=c,n=0,min=0;if(c<128)continue;if(c>=0xc2&&c<=0xdf){n=1;value=c&31;min=128;}else if(c>=0xe0&&c<=0xef){n=2;value=c&15;min=2048;}else if(c>=0xf0&&c<=0xf4){n=3;value=c&7;min=65536;}else return false;if(n>b.size()-p)return false;while(n--){c=b[p++];if((c&192)!=128)return false;value=(value<<6)|(c&63);}if(value<min||value>0x10ffff||(value>=0xd800&&value<=0xdfff))return false;}return true;}
inline std::string text(const Bytes& b){return utf8(b)?std::string(b.begin(),b.end()):"[unknown encoding: "+hex(b)+"]";}
struct Reader {
 const Bytes& b;size_t p=0;
 void need(size_t n)const{if(n>b.size()-p)throw std::runtime_error("Truncated class at byte "+std::to_string(p));}
 uint8_t u8(){need(1);return b[p++];}uint16_t u16(){auto a=u8();return uint16_t(a)*256+u8();}uint32_t u32(){auto a=u16();return uint32_t(a)*65536+u16();}void skip(size_t n){need(n);p+=n;}
};
inline J javaClass(const Bytes& bytes){J out={{"status","not_class"},{"execution","not_executed"}};if(bytes.size()<4||hex(bytes.data(),4)!="CAFEBABE")return out;Reader r{bytes};try{
 r.skip(4);out["minor"]=r.u16();out["major"]=r.u16();const unsigned count=r.u16();if(!count)throw std::runtime_error("Empty constant pool");out["constant_pool_count"]=count;
 struct Constant{unsigned tag=0,ref=0;std::string value;};std::vector<Constant> pool(count);J strings=J::array();size_t stringCount=0;
 for(unsigned i=1;i<count;++i){auto& c=pool[i];c.tag=r.u8();switch(c.tag){case 1:{size_t n=r.u16();r.need(n);Bytes value(bytes.begin()+r.p,bytes.begin()+r.p+n);c.value=text(value);if(strings.size()<1000)strings.push_back({{"index",i},{"offset",r.p},{"bytes",n},{"text",c.value},{"encoding",utf8(value)?"UTF-8 compatible subset of modified UTF-8":"modified UTF-8 retained as hex"}});++stringCount;r.skip(n);break;}case 7:case 8:case 16:case 19:case 20:c.ref=r.u16();break;case 15:r.skip(3);break;case 3:case 4:case 9:case 10:case 11:case 12:case 17:case 18:r.skip(4);break;case 5:case 6:r.skip(8);if(++i>=count)throw std::runtime_error("Wide constant lacks reserved slot");break;default:throw std::runtime_error("Unsupported constant pool tag "+std::to_string(c.tag));}}
 auto stringAt=[&](unsigned i){if(!i||i>=count||pool[i].tag!=1)throw std::runtime_error("Invalid UTF-8 constant reference");return pool[i].value;};
 auto classAt=[&](unsigned i){if(!i)return std::string();if(i>=count||pool[i].tag!=7)throw std::runtime_error("Invalid class reference");return stringAt(pool[i].ref);};
 auto attributes=[&](){unsigned n=r.u16();for(unsigned j=0;j<n;++j){stringAt(r.u16());r.skip(r.u32());}};
 out["access_flags"]=r.u16();out["class_name"]=classAt(r.u16());out["super_name"]=classAt(r.u16());out["interfaces"]=J::array();unsigned interfaces=r.u16();for(unsigned i=0;i<interfaces;++i)out["interfaces"].push_back(classAt(r.u16()));
 for(const char* kind:{"fields","methods"}){unsigned n=r.u16();out[std::string(kind)+"_count"]=n;out[kind]=J::array();if(n>4096)throw std::runtime_error("Class member limit exceeded (4096)");for(unsigned i=0;i<n;++i){size_t offset=r.p;unsigned flags=r.u16();auto name=stringAt(r.u16()),descriptor=stringAt(r.u16());attributes();out[kind].push_back({{"offset",offset},{"name",name},{"descriptor",descriptor},{"access_flags",flags}});}}
 attributes();if(r.p!=bytes.size())throw std::runtime_error("Trailing class bytes");out["strings"]=strings;out["string_total"]=stringCount;out["status"]="parsed";out["scope"]="Read-only class envelope and names; attributes retained in raw bytes, no bytecode verification or execution";
 }catch(const std::exception& e){out["status"]="invalid_or_unsupported";out["error"]=e.what();out["error_offset"]=r.p;}return out;}
inline J page(const Bytes& bytes,size_t offset,size_t limit){if(offset>bytes.size())throw std::runtime_error("Content offset outside extent");size_t end=offset+std::min(limit,bytes.size()-offset);J out={{"offset",offset},{"length",end-offset},{"total_bytes",bytes.size()},{"raw_hex",hex(bytes.data()+offset,end-offset)},{"sha256",sha(bytes)},{"next_offset",end<bytes.size()?J(end):J()},{"execution","not_executed"},{"encoding","unknown"}};
 if(utf8(bytes)){size_t begin=offset,stop=end;while(begin<stop&&(bytes[begin]&192)==128)++begin;while(stop>begin&&stop<bytes.size()&&(bytes[stop]&192)==128)--stop;out["encoding"]="UTF-8";out["text_offset"]=begin;out["text_length"]=stop-begin;out["text"]=std::string(bytes.begin()+begin,bytes.begin()+stop);}out["class_info"]=javaClass(bytes);return out;}
inline Bytes assemble(const dsmccsignalling::ModuleState& state){Bytes bytes;if(state.status!="complete")return bytes;bytes.reserve(state.size);for(const auto& [number,record]:state.blocks)bytes.insert(bytes.end(),record->raw.begin()+26,record->raw.end()-4);if(bytes.size()!=state.size||sha(bytes)!=state.sha256)throw std::runtime_error("Module reconstruction identity changed");return bytes;}
inline J object(const biopwire::BiopMessage& object,size_t offset){return {{"offset",offset},{"envelope_bytes",object.raw.size()},{"key_hex",hex(object.object_key)},{"type",biopwire::biop_kind_name(object.object_kind)},{"kind",object.object_kind},{"body_bytes",object.body.size()},{"content_bytes",object.object_kind==0x66696c00?J(object.content.size()):J()},{"content_offset",object.object_kind==0x66696c00?J(offset+object.raw.size()-object.content.size()):J()},{"content_sha256",object.object_kind==0x66696c00?J(sha(object.content)):J()},{"binding_count",object.bindings.size()},{"object_info_hex",hex(object.object_info)}};}
inline J profile(const biopwire::BiopIorProfile& p){return {{"profile_id",p.profile_id},{"raw_hex",hex(p.data)},{"parsed",p.body_parsed},{"location_parsed",p.location_parsed},{"key_hex",hex(p.object_key)},{"module_id",p.location_parsed?J(p.module_id):J()},{"carousel_id",p.location_parsed?J(p.carousel_id):J()},{"legacy_module_version",p.legacy_module_version?J(p.module_version):J()},{"biop_version",J::array({p.biop_version_major,p.biop_version_minor})},{"kind",p.object_kind}};}
